// expectedEncryptedSize returns the exact wire size of a V2 at-rest container
// generated by the writer for this plaintext size.
func expectedEncryptedSize(plaintext int64) int64 {
	header := int64(len(AtRestMagicHeader)) + int64(AtRestBaseNonceSize) + int64(AtRestFrameHeaderSize)
	dataFrames := int64(0)
	if plaintext > 0 {
		dataFrames = (plaintext + int64(AtRestSegmentSize) - 1) / int64(AtRestSegmentSize)
	}
	eofFrame := int64(AtRestFrameHeaderSize) + 16
	dataOverhead := dataFrames * (int64(AtRestFrameHeaderSize) + 16)
	return header + dataOverhead + eofFrame + plaintext
}

// smallChunkReader replays a byte slice in deterministically varied tiny pieces,
// exercising writer buffering across arbitrary write boundaries.
type smallChunkReader struct {
	data []byte
	off  int
	call int
}

func (r *smallChunkReader) Read(p []byte) (int, error) {
	if r.off >= len(r.data) {
		return 0, io.EOF
	}
	max := 1 + (r.call*7)%43 // varied 1..43 bytes
	if max > len(p) {
		max = len(p)
	}
	if max > len(r.data)-r.off {
		max = len(r.data) - r.off
	}
	copy(p[:max], r.data[r.off:r.off+max])
	r.off += max
	r.call++
	return max, nil
}

func TestAtRest_EncryptDecrypt_Success(t *testing.T) {
	testSizes := []struct {
		name string
		size int
	}{
		{name: "Empty", size: 0},
		{name: "1_Byte", size: 1},
		{name: "100_Bytes", size: 100},
		{name: "Segment_Aligned_4MB", size: 4 * 1024 * 1024},
		{name: "Segment_Plus_One", size: 4*1024*1024 + 1},
		{name: "9_MB_Multi_Segment", size: 9 * 1024 * 1024},
	}

	key := make([]byte, AtRestKeySize)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("key generation failed: %v", err)
	}

	for _, tc := range testSizes {
		t.Run(tc.name, func(t *testing.T) {
			originalData := make([]byte, tc.size)
			if _, err := io.ReadFull(rand.Reader, originalData); err != nil {
				t.Fatalf("failed to generate random data: %v", err)
			}

			// 1. Encrypt stream
			var encryptedBuf bytes.Buffer
			if err := EncryptStream(bytes.NewReader(originalData), &encryptedBuf, key); err != nil {
				t.Fatalf("EncryptStream failed: %v", err)
			}

			encryptedBytes := encryptedBuf.Bytes()
			expectedLen := expectedEncryptedSize(int64(tc.size))
			if int64(len(encryptedBytes)) != expectedLen {
				t.Fatalf("expected encrypted size %d, got %d", expectedLen, len(encryptedBytes))
			}

			// 2. Writer must produce identical framing for small scattered writes
			var scatteredBuf bytes.Buffer
			w, err := NewAtRestWriter(&scatteredBuf, key)
			if err != nil {
				t.Fatalf("NewAtRestWriter failed: %v", err)
			}
			if _, err := io.CopyBuffer(w, &smallChunkReader{data: originalData}, make([]byte, 97)); err != nil {
				t.Fatalf("chunked write failed: %v", err)
			}
			if err := w.Close(); err != nil {
				t.Fatalf("writer Close failed: %v", err)
			}
			if scatteredBuf.Len() != len(encryptedBytes) {
				t.Fatalf("scattered writes produced different size: %d vs %d", scatteredBuf.Len(), len(encryptedBytes))
			}

			// 3. Test IsEncrypted across various reader types
			// A. *bytes.Reader (io.ReadSeeker)
			bytesReader := bytes.NewReader(encryptedBytes)
			isEnc, err := IsEncrypted(bytesReader)
			if err != nil {
				t.Fatalf("IsEncrypted (*bytes.Reader) error: %v", err)
			}
			if !isEnc {
				t.Fatalf("expected IsEncrypted (*bytes.Reader) to be true")
			}
			pos, _ := bytesReader.Seek(0, io.SeekCurrent)
			if pos != 0 {
				t.Fatalf("expected reader position 0, got %d", pos)
			}

			// B. *bufio.Reader
			bufReader := bufio.NewReader(bytes.NewReader(encryptedBytes))
			isEnc, err = IsEncrypted(bufReader)
			if err != nil {
				t.Fatalf("IsEncrypted (*bufio.Reader) error: %v", err)
			}
			if !isEnc {
				t.Fatalf("expected IsEncrypted (*bufio.Reader) to be true")
			}
			firstByte, err := bufReader.ReadByte()
			if err != nil || firstByte != 'H' {
				t.Fatalf("expected first byte 'H', got %v (err: %v)", firstByte, err)
			}

			// C. *bytes.Buffer
			bufCopy := bytes.NewBuffer(encryptedBytes)
			isEnc, err = IsEncrypted(bufCopy)
			if err != nil {
				t.Fatalf("IsEncrypted (*bytes.Buffer) error: %v", err)
			}
			if !isEnc {
				t.Fatalf("expected IsEncrypted (*bytes.Buffer) to be true")
			}
			if bufCopy.Len() != len(encryptedBytes) {
				t.Fatalf("expected buffer length unchanged, got %d", bufCopy.Len())
			}

			// D. *os.File
			tmpFile, err := os.CreateTemp("", "hushdrop_atrest_test_*")
			if err != nil {
				t.Fatalf("failed to create temp file: %v", err)
			}
			defer os.Remove(tmpFile.Name())
			defer tmpFile.Close()

			if _, err := tmpFile.Write(encryptedBytes); err != nil {
				t.Fatalf("failed to write to temp file: %v", err)
			}
			if _, err := tmpFile.Seek(0, io.SeekStart); err != nil {
				t.Fatalf("failed to seek temp file: %v", err)
			}

			isEnc, err = IsEncrypted(tmpFile)
			if err != nil {
				t.Fatalf("IsEncrypted (*os.File) error: %v", err)
			}
			if !isEnc {
				t.Fatalf("expected IsEncrypted (*os.File) to be true")
			}
			filePos, _ := tmpFile.Seek(0, io.SeekCurrent)
			if filePos != 0 {
				t.Fatalf("expected file position 0, got %d", filePos)
			}

			// 4. Decrypt stream
			decSrc := bytes.NewReader(copyBytes(encryptedBytes))
			var decryptedBuf bytes.Buffer
			if err := DecryptStream(decSrc, &decryptedBuf, key); err != nil {
				t.Fatalf("DecryptStream failed: %v", err)
			}

			if !bytes.Equal(originalData, decryptedBuf.Bytes()) {
				t.Fatalf("decrypted data does not match original data (len %d vs %d)", len(originalData), decryptedBuf.Len())
			}

			// 5. Incremental reader path must match too
			decReader, err := NewAtRestReader(bytes.NewReader(copyBytes(encryptedBytes)), key)
			if err != nil {
				t.Fatalf("NewAtRestReader failed: %v", err)
			}
			incremental, err := io.ReadAll(decReader)
			if err != nil {
				t.Fatalf("incremental read failed: %v", err)
			}
			if !bytes.Equal(originalData, incremental) {
				t.Fatalf("incremental decrypt mismatch (len %d vs %d)", len(originalData), len(incremental))
			}
		})
	}
}

func copyBytes(b []byte) []byte {
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

func TestAtRest_WrongKey(t *testing.T) {
	data := []byte("Sensitive HushDrop message to be encrypted at rest")
	key := make([]byte, AtRestKeySize)
	wrongKey := make([]byte, AtRestKeySize)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("key generation failed: %v", err)
	}
	if _, err := rand.Read(wrongKey); err != nil {
		t.Fatalf("key generation failed: %v", err)
	}

	var encryptedBuf bytes.Buffer
	if err := EncryptStream(bytes.NewReader(data), &encryptedBuf, key); err != nil {
		t.Fatalf("EncryptStream failed: %v", err)
	}

	var decryptedBuf bytes.Buffer
	err := DecryptStream(bytes.NewReader(encryptedBuf.Bytes()), &decryptedBuf, wrongKey)
	if err == nil {
		t.Fatalf("expected error when decrypting with wrong key, got nil")
	}
	if !errors.Is(err, ErrInvalidKey) {
		t.Fatalf("expected ErrInvalidKey, got: %v", err)
	}
	if decryptedBuf.Len() > 0 {
		t.Fatalf("expected no output on decryption failure, got %d bytes", decryptedBuf.Len())
	}
}

func TestAtRest_CorruptedCiphertext(t *testing.T) {
	data := []byte("Sensitive HushDrop payload that will have bytes corrupted")
	key := make([]byte, AtRestKeySize)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("key generation failed: %v", err)
	}

	var encryptedBuf bytes.Buffer
	if err := EncryptStream(bytes.NewReader(data), &encryptedBuf, key); err != nil {
		t.Fatalf("EncryptStream failed: %v", err)
	}
	encryptedBytes := encryptedBuf.Bytes()
	// Wire layout: magic(16) + base(8) + segLen(4) = 28, then len(4) + ciphertext+tag.
	const firstFrameBody = len(AtRestMagicHeader) + AtRestBaseNonceSize + AtRestFrameHeaderSize + AtRestFrameHeaderSize

	t.Run("CorruptedPayloadByte", func(t *testing.T) {
		corrupted := copyBytes(encryptedBytes)
		corrupted[firstFrameBody] ^= 0xFF

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(corrupted), &decryptedBuf, key)
		if !errors.Is(err, ErrInvalidKey) {
			t.Fatalf("expected ErrInvalidKey on corrupted payload, got: %v", err)
		}
		if decryptedBuf.Len() > 0 {
			t.Fatalf("expected no output on corrupted payload, got %d bytes", decryptedBuf.Len())
		}
	})

	t.Run("CorruptedEofTagByte", func(t *testing.T) {
		corrupted := copyBytes(encryptedBytes)
		corrupted[len(corrupted)-1] ^= 0xAA

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(corrupted), &decryptedBuf, key)
		if !errors.Is(err, ErrInvalidKey) {
			t.Fatalf("expected ErrInvalidKey on corrupted eof tag, got: %v", err)
		}
	})

	t.Run("CorruptedBaseNonce", func(t *testing.T) {
		corrupted := copyBytes(encryptedBytes)
		corrupted[len(AtRestMagicHeader)] ^= 0x55

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(corrupted), &decryptedBuf, key)
		if !errors.Is(err, ErrInvalidKey) {
			t.Fatalf("expected ErrInvalidKey on corrupted base nonce, got: %v", err)
		}
	})

	t.Run("JumboFrameLengthPrefix", func(t *testing.T) {
		corrupted := copyBytes(encryptedBytes)
		// Frame length prefix sits right before the ciphertext (index 28).
		binary.BigEndian.PutUint32(corrupted[len(AtRestMagicHeader)+AtRestBaseNonceSize:], math.MaxUint32)

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(corrupted), &decryptedBuf, key)
		if !errors.Is(err, ErrCorruptFrame) {
			t.Fatalf("expected ErrCorruptFrame on jumbo length prefix, got: %v", err)
		}
	})

	t.Run("TruncatedMidFrame", func(t *testing.T) {
		truncated := encryptedBytes[:len(encryptedBytes)-24]

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(truncated), &decryptedBuf, key)
		if !errors.Is(err, ErrCorruptFrame) {
			t.Fatalf("expected ErrCorruptFrame on truncated stream, got: %v", err)
		}
	})

	t.Run("MissingEofFrame", func(t *testing.T) {
		// Cut exactly the eof frame (4 + 16 bytes) so all data frames stay intact.
		kept := encryptedBytes[:len(encryptedBytes)-int(AtRestFrameHeaderSize)-16]

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(kept), &decryptedBuf, key)
		if !errors.Is(err, ErrCorruptFrame) {
			t.Fatalf("expected ErrCorruptFrame when eof frame missing, got: %v", err)
		}
	})

	t.Run("TrailingJunkAfterEof", func(t *testing.T) {
		tampered := append(copyBytes(encryptedBytes), 0x00)

		var decryptedBuf bytes.Buffer
		err := DecryptStream(bytes.NewReader(tampered), &decryptedBuf, key)
		if !errors.Is(err, ErrCorruptFrame) {
			t.Fatalf("expected ErrCorruptFrame on trailing data, got: %v", err)
		}
	})
}

func TestAtRest_IsEncrypted_Unencrypted(t *testing.T) {
	plainData := []byte("This is plain unencrypted text that does not have hushdrop header.")

	isEnc, err := IsEncrypted(bytes.NewReader(plainData))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if isEnc {
		t.Fatalf("expected plainData to not be marked encrypted")
	}

	shortData := []byte("short")
	isEnc, err = IsEncrypted(bytes.NewReader(shortData))
	if err != nil {
		t.Fatalf("unexpected error on short data: %v", err)
	}
	if isEnc {
		t.Fatalf("expected shortData to not be marked encrypted")
	}

	isEnc, err = IsEncrypted(bytes.NewReader([]byte{}))
	if err != nil {
		t.Fatalf("unexpected error on empty data: %v", err)
	}
	if isEnc {
		t.Fatalf("expected empty data to not be marked encrypted")
	}
}

func TestAtRest_InvalidHeader(t *testing.T) {
	fakeData := []byte("SOME_RANDOM_HEAD16BYTES_OF_DATA_PLUS_MORE")
	var decryptedBuf bytes.Buffer
	err := DecryptStream(bytes.NewReader(fakeData), &decryptedBuf, make([]byte, AtRestKeySize))
	if !errors.Is(err, ErrInvalidHeader) {
		t.Fatalf("expected ErrInvalidHeader, got: %v", err)
	}

	// Truncated header (< 28 bytes) must also fail cleanly.
	var out bytes.Buffer
	err = DecryptStream(bytes.NewReader(make([]byte, 10)), &out, make([]byte, AtRestKeySize))
	if !errors.Is(err, ErrInvalidHeader) {
		t.Fatalf("expected ErrInvalidHeader on short stream, got: %v", err)
	}
}

func TestAtRest_BadKeyLength(t *testing.T) {
	data := []byte("test data")
	var buf bytes.Buffer
	if err := EncryptStream(bytes.NewReader(data), &buf, make([]byte, 16)); !errors.Is(err, ErrInvalidKey) {
		t.Fatalf("expected ErrInvalidKey for short key in EncryptStream, got: %v", err)
	}

	smallKey := make([]byte, 8)
	rSmall, err := NewAtRestReader(bytes.NewReader(nil), smallKey)
	if err == nil || rSmall != nil {
		t.Fatalf("expected error from NewAtRestReader with short key, got %v", err)
	}
}

func TestAtRest_KeyFile_LoadOrCreate(t *testing.T) {
	dir := t.TempDir()
	keyPath := filepath.Join(dir, "sub", AtRestKeyFileName)

	key1, err := LoadOrCreateAtRestKey(keyPath)
	if err != nil {
		t.Fatalf("LoadOrCreateAtRestKey (create) failed: %v", err)
	}
	if len(key1) != AtRestKeySize {
		t.Fatalf("expected %d-byte key, got %d", AtRestKeySize, len(key1))
	}
	if runtime.GOOS != "windows" {
		info, err := os.Stat(keyPath)
		if err != nil {
			t.Fatalf("stat key file failed: %v", err)
		}
		if perm := info.Mode().Perm(); perm != 0600 {
			t.Fatalf("expected key file perm 0600, got %o", perm)
		}
	}

	key2, err := LoadOrCreateAtRestKey(keyPath)
	if err != nil {
		t.Fatalf("LoadOrCreateAtRestKey (load) failed: %v", err)
	}
	if !bytes.Equal(key1, key2) {
		t.Fatalf("reloaded key differs from stored key")
	}

	// Corrupted (wrong size) key file must be rejected instead of silently used.
	if err := os.WriteFile(keyPath, make([]byte, 8), 0600); err != nil {
		t.Fatalf("failed to overwrite key file: %v", err)
	}
	if _, err := LoadOrCreateAtRestKey(keyPath); err == nil {
		t.Fatalf("expected error for wrong-size key file")
	}

	if _, err := LoadOrCreateAtRestKey(""); err == nil {
		t.Fatalf("expected error for empty path")
	}
}

func TestAtRest_WriterLifecycle(t *testing.T) {
	key := make([]byte, AtRestKeySize)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("key generation failed: %v", err)
	}

	var buf bytes.Buffer
	w, err := NewAtRestWriter(&buf, key)
	if err != nil {
		t.Fatalf("NewAtRestWriter: %v", err)
	}
	if _, err := w.Write([]byte("hello")); err != nil {
		t.Fatalf("Write: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	// Close is idempotent per io.WriteCloser contract.
	if err := w.Close(); err != nil {
		t.Fatalf("second Close must stay nil, got: %v", err)
	}
	if _, err := w.Write([]byte("more")); !errors.Is(err, ErrWriteAfterClose) && err == nil {
		t.Fatalf("expected ErrWriteAfterClose after close, got: %v", err)
	}

	// Empty file round-trip through the writer only.
	var emptyBuf bytes.Buffer
	ew, err := NewAtRestWriter(&emptyBuf, key)
	if err != nil {
		t.Fatalf("NewAtRestWriter: %v", err)
	}
	if err := ew.Close(); err != nil {
		t.Fatalf("Close empty: %v", err)
	}
	if emptyBuf.Len() != int(expectedEncryptedSize(0)) {
		t.Fatalf("empty container size mismatch: %d vs %d", emptyBuf.Len(), expectedEncryptedSize(0))
	}
	var plain bytes.Buffer
	if err := DecryptStream(bytes.NewReader(emptyBuf.Bytes()), &plain, key); err != nil {
		t.Fatalf("decrypt empty: %v", err)
	}
	if plain.Len() != 0 {
		t.Fatalf("expected empty plaintext, got %d bytes", plain.Len())
	}
}

func TestAtRest_PeekHelper(t *testing.T) {
	data := []byte("Plain text test for peek helper")
	r := bytes.NewReader(data)

	isEnc, restoredReader, err := PeekIsEncrypted(r)
	if err != nil {
		t.Fatalf("PeekIsEncrypted error: %v", err)
	}
	if isEnc {
		t.Fatalf("expected isEnc false")
	}

	readAll, err := io.ReadAll(restoredReader)
	if err != nil {
		t.Fatalf("ReadAll error: %v", err)
	}
	if !bytes.Equal(readAll, data) {
		t.Fatalf("restoredReader did not return all original data")
	}
}

// Sanity: segment size constant must be within the safe range for the reader guard.
func TestAtRest_SegmentSize_Sanity(t *testing.T) {
	if AtRestSegmentSize <= 0 || AtRestSegmentSize > 1<<31 {
		t.Fatalf("AtRestSegmentSize out of safe range: %d", AtRestSegmentSize)
	}
	if AtRestBaseNonceSize+4 != 12 {
		t.Fatalf("nonce composition must be 12 bytes, got %d", AtRestBaseNonceSize+4)
	}
	if len(AtRestMagicHeader) != 16 {
		t.Fatalf("magic header must be 16 bytes, got %d", len(AtRestMagicHeader))
	}
}
